132		// an answer outside 2xx is read for it and dropped.
133		remoteURLBlocked bool
134		// remoteURLPrivate is the verdict of remoteURLPrivate on the same 400.
135		remoteURLPrivate bool
136	}
137	
138	// do sends r and returns the answer whatever its status. The error is a
139	// *transportError or a *tooLargeError.
140	func (c *client) do(ctx context.Context, r request) (response, error) {
141		target := c.base + r.path
142		if len(r.query) > 0 {
143			target += "?" + r.query.Encode()
144		}
145		var body io.Reader
146		if r.body != nil {
147			body = bytes.NewReader(r.body)
148		}
149		req, err := http.NewRequestWithContext(ctx, r.method, target, body)
150		if err != nil {
151			return response{}, &transportError{Op: r.op, Err: err}
152		}
153		req.Header.Set("Accept", "application/json")
154		if r.contentType != "" {
155			req.Header.Set("Content-Type", r.contentType)
156		}
157		if c.user != "" {
158			req.SetBasicAuth(c.user, c.REDACTED)
159		}
160		resp, err := c.http.Do(req)
161		if err != nil {
162			return response{}, &transportError{Op: r.op, Err: err}
163		}
164		defer func() { _ = resp.Body.Close() }()
165		if resp.StatusCode < 200 || resp.StatusCode > 299 {
166			refused, _ := io.ReadAll(io.LimitReader(resp.Body, drainBytes))
167			badRequest := resp.StatusCode == http.StatusBadRequest
168			return response{
169				status: resp.StatusCode, header: resp.Header,
170				remoteURLBlocked: badRequest && remoteURLRefused(refused),
171				remoteURLPrivate: badRequest && remoteURLPrivate(refused),
172			}, nil
173		}
174		data, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes+1))
175		if err != nil {
176			return response{}, &transportError{Op: r.op, Err: err}
177		}
178		if len(data) > maxResponseBytes {
179			return response{}, &tooLargeError{Op: r.op}
180		}
181		return response{status: resp.StatusCode, header: resp.Header, body: data}, nil
182	}
183	
184	// expect sends r and turns a status outside 2xx into an *APIError.
185	func (c *client) expect(ctx context.Context, r request) (response, error) {
186		resp, err := c.do(ctx, r)
187		if err != nil {
188			return resp, err
189		}
190		if resp.status < 200 || resp.status > 299 {
191			return resp, &APIError{Op: r.op, Status: resp.status, RemoteURLBlocked: resp.remoteURLBlocked, RemoteURLPrivate: resp.remoteURLPrivate}
192		}
193		return resp, nil
194	}
195	
196	// remoteURLRefused reports whether body is a Nexus validation error list with
197	// an entry on proxy.remoteUrl whose message says the host did not resolve:
198	// [{"id":"HelperBean.proxy.remoteUrl","message":"... Failed to resolve host: ..."}].
199	// Only that verdict leaves the function: no text of the answer is kept. The
200	// content type of the answer is vendor specific, so only the JSON is read; a
201	// body past drainBytes was cut and is not trusted.
202	func remoteURLRefused(body []byte) bool {
203		return remoteURLMessageHas(body, "resolve host")
204	}
205	
206	// remoteURLPrivate reports whether body is a validation error list with an entry
207	// on proxy.remoteUrl that says the host resolves to a private address, which is
208	// what the SSRF protection of Nexus 3.98 answers (observed on 3.98.1-01:
209	// "Proxy URL blocked: Host resolves to private/local IP address(es): ..."). Same
210	// rules as remoteURLRefused: only the verdict leaves the function.
211	func remoteURLPrivate(body []byte) bool {
212		return remoteURLMessageHas(body, "resolves to private")
213	}
214	
215	// remoteURLMessageHas reports whether body is a validation error list with an
216	// entry on proxy.remoteUrl whose message contains fragment, case-insensitive.
217	func remoteURLMessageHas(body []byte, fragment string) bool {
218		if len(body) > drainBytes {
219			return false
220		}
221		var errs []validationError
222		if err := json.Unmarshal(body, &errs); err != nil {
223			return false
224		}
225		return slices.ContainsFunc(errs, func(e validationError) bool {
226			return strings.HasSuffix(e.ID, "proxy.remoteUrl") &&
227				strings.Contains(strings.ToLower(e.Message), fragment)
228		})
229	}
230	
231	// validationError is one entry of a Nexus validation error list. The message is
232	// only matched by remoteURLRefused, never stored or shown.
233	type validationError struct {
234		ID      string `json:"id"`
235		Message string `json:"message"`
236	}
237	
238	// get reads path and decodes the JSON answer into out (nil: not decoded). A 404
239	// is found == false without an error.
240	func (c *client) get(ctx context.Context, op, path string, query url.Values, out any) (found bool, err error) {
241		resp, err := c.do(ctx, request{op: op, method: http.MethodGet, path: path, query: query})
242		if err != nil {
243			return false, err
244		}
245		switch {
246		case resp.status == http.StatusNotFound:
247			return false, nil
248		case resp.status < 200 || resp.status > 299:
249			return false, &APIError{Op: op, Status: resp.status}
250		}
251		if out == nil {
252			return true, nil
253		}
254		if err := json.Unmarshal(resp.body, out); err != nil {
255			return false, &decodeError{Op: op, Err: err}
256		}
257		return true, nil
258	}
259	
260	// read is get for an object that has to exist: a 404 is an *APIError.
261	func (c *client) read(ctx context.Context, op, path string, query url.Values, out any) error {
262		found, err := c.get(ctx, op, path, query, out)
263		if err != nil {
264			return err
265		}
266		if !found {
267			return &APIError{Op: op, Status: http.StatusNotFound}
268		}
269		return nil
270	}
271	
272	// write sends payload as JSON with method and expects a 2xx.
273	func (c *client) write(ctx context.Context, op, method, path string, payload any) error {
274		data, err := json.Marshal(payload)
275		if err != nil {
276			return &decodeError{Op: op, Err: err}
277		}
278		_, err = c.expect(ctx, request{op: op, method: method, path: path, contentType: "application/json", body: data})
279		return err
280	}
