11	// upstreamPollInterval separates two rounds of the wait for the upstream. It is
12	// shorter than pollInterval: a registry is ready within seconds of its image
13	// being local, and the wait has no host to probe.
14	const upstreamPollInterval = 2 * time.Second
15	
16	// UpstreamState is what the cluster says about the bench upstream registry.
17	type UpstreamState int
18	
19	// The states of the upstream, from the least to the most alive.
20	const (
21		// UpstreamMissing: the Deployment bench-upstream does not exist.
22		UpstreamMissing UpstreamState = iota
23		// UpstreamCut: the Deployment exists with zero replicas.
24		UpstreamCut
25		// UpstreamStarting: one replica is wanted and no pod of it is ready yet.
26		UpstreamStarting
27		// UpstreamReady: a pod of the upstream that is not terminating is ready.
28		UpstreamReady
29	)
30	
31	// ReadUpstream reads the state of the bench upstream with read-only kubectl
32	// calls: it writes nothing and waits for nothing. A pod that fails to pull is
33	// Starting, not an error: diagnosing is the job of the wait. It runs no
34	// preflight; the caller does. Every failure is a *BenchError, but a cancelled
35	// context, which is returned as is.
36	func ReadUpstream(ctx context.Context, r Runner, p Params) (UpstreamState, error) {
37		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", out: io.Discard}
38		return d.readUpstream(ctx)
39	}
40	
41	// EnsureUpstream brings the bench upstream to one ready replica, and returns
42	// when it is ready or fails with a diagnosis. It reads first and writes only
43	// when the upstream is cut: one scale to one replica, then the wait. A starting
44	// upstream is waited for without a write; a ready one is left alone. The
45	// Deployment itself is applied by Deploy, so a missing one is an error. A
46	// custom upstream (Params.UpstreamIsBench is false) is refused before any call:
47	// the bench scales what it deploys and nothing else. The wait polls the pods
48	// and the claim of the upstream only, until Params.Timeout. It runs no
49	// preflight; the caller does. Every failure is a *BenchError, but a cancelled
50	// context, which is returned as is. A nil out discards the progress lines.
51	func EnsureUpstream(ctx context.Context, r Runner, clk Clock, p Params, out io.Writer) error {
52		if out == nil {
53			out = io.Discard
54		}
55		if !p.UpstreamIsBench() {
56			return customUpstreamError(p)
57		}
58		// The runner of a test may ignore ctx; the first call must not depend on it.
59		if err := ctx.Err(); err != nil {
60			return err
61		}
62		d := &deployer{pf: preflight{r: r, p: p}, w: upstreamWorkload(), tag: "upstream", clk: clk, out: out}
63		state, err := d.readUpstream(ctx)
64		if err != nil {
65			return err
66		}
67		switch state {
68		case UpstreamMissing:
69			return &BenchError{
70				Kind:  Unclassified,
71				Cause: fmt.Sprintf("the Deployment %s does not exist in namespace %q", upstreamDeployment, p.Namespace),
72				Check: "run `mise run nexus-bench:up`, which applies it, or " + d.pf.command("get", "deployment", upstreamDeployment, "-n", p.Namespace),
73			}
74		case UpstreamReady:
75			d.say("the upstream is ready")
76			return nil
77		case UpstreamCut:
78			d.say("scaling the upstream to one replica")
79			if err := d.scaleUpstream(ctx, 1); err != nil {
80				return err
81			}
82		case UpstreamStarting:
83			d.say("the upstream is starting")
84		}
85		return d.waitUpstream(ctx)
86	}
87	
88	// customUpstreamError refuses an upstream the bench does not deploy.
89	func customUpstreamError(p Params) *BenchError {
90		return &BenchError{
91			Kind: Unclassified,
92			Cause: fmt.Sprintf("%s points at an upstream the bench did not deploy in namespace %q, and the bench scales only its own upstream",
93				envUpstreamURL, p.Namespace),
94			Check: "unset " + envUpstreamURL + " to use the bench upstream, or start and stop your own upstream registry yourself",
95		}
96	}
