270	func (u *upstreamKubectl) deploymentObject(name string, replicas int, pods []upPod) map[string]any {
271		ready := 0
272		for _, pd := range pods {
273			if pd.ready && !pd.terminating {
274				ready++
275			}
276		}
277		return map[string]any{
278			"metadata": map[string]any{"name": name, "namespace": u.p.Namespace, "labels": map[string]string{"app.kubernetes.io/name": name}},
279			"spec":     map[string]any{"replicas": replicas},
280			"status":   map[string]any{"replicas": len(pods), "readyReplicas": ready, "availableReplicas": ready},
281		}
282	}
