284	func (u *upstreamKubectl) answerDeployments(g getCall, round upstreamRound) ([]byte, []byte, error) {
285		if u.deploymentReply != nil {
286			return u.deploymentReply.reply()
287		}
288		if g.name != "" && g.name != upstreamName {
289			u.t.Errorf("get deployment %q: the upstream lifecycle is about %q only", g.name, upstreamName)
290			return notFoundReply("deployments.apps \"" + g.name + "\"")
291		}
292		if g.selector != "" && g.selector != upstreamSelector {
293			u.t.Errorf("get deployment -l %q: not the upstream", g.selector)
294		}
295		if g.name == upstreamName {
296			if !round.deployment {
297				return notFoundReply("deployments.apps \"" + upstreamName + "\"")
298			}
299			return u.mustJSON(u.deploymentObject(upstreamName, round.replicas, round.pods)), nil, nil
300		}
301		// Nexus first: a reader that takes the first item reads the wrong one.
302		items := []any{u.deploymentObject("nexus", 1, nil)}
303		if round.deployment {
304			items = append(items, u.deploymentObject(upstreamName, round.replicas, round.pods))
305		}
306		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
307	}
308	
309	func (u *upstreamKubectl) answerPods(g getCall, round upstreamRound) ([]byte, []byte, error) {
310		if u.podsReply != nil {
311			return u.podsReply.reply()
312		}
313		if g.selector != upstreamSelector {
314			u.t.Errorf("get pods selects %q, want %q", g.selector, upstreamSelector)
315		}
316		items := []any{}
317		for _, pd := range round.pods {
318			items = append(items, pd.object())
319		}
320		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
321	}
322	
323	func (u *upstreamKubectl) claimObject(name, app, phase string) map[string]any {
324		return map[string]any{
325			"metadata": map[string]any{"name": name, "labels": map[string]string{"app.kubernetes.io/name": app}},
326			"status":   map[string]any{"phase": phase},
327		}
328	}
329	
330	func (u *upstreamKubectl) answerClaims(g getCall, round upstreamRound) ([]byte, []byte, error) {
331		nexusPhase := round.nexusClaim
332		if nexusPhase == "" {
333			nexusPhase = "Bound"
334		}
335		// Nexus first, against the order of kubectl: the reader must pick by name.
336		claims := []map[string]any{u.claimObject(deployPVCName, "nexus", nexusPhase)}
337		if round.claim != "" {
338			claims = append(claims, u.claimObject(upstreamClaim, upstreamName, round.claim))
339		}
340		var items []any
341		for _, c := range claims {
342			name := c["metadata"].(map[string]any)["name"]
343			app := c["metadata"].(map[string]any)["labels"].(map[string]string)["app.kubernetes.io/name"]
344			if g.name != "" && g.name != name {
345				continue
346			}
347			if g.selector != "" && g.selector != "app.kubernetes.io/name="+app {
348				continue
349			}
350			items = append(items, c)
351		}
352		if g.name != "" {
353			if len(items) == 0 {
354				return notFoundReply("persistentvolumeclaims \"" + g.name + "\"")
355			}
356			return u.mustJSON(items[0]), nil, nil
357		}
358		if items == nil {
359			items = []any{}
360		}
361		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
362	}
