445	// requireOneScale checks the one write is the scale to the replicas.
446	func (e *upstreamEnv) requireOneScale(replicas string) {
447		e.t.Helper()
448		if len(e.kube.writes) != 1 || len(e.kube.scales) != 1 {
449			e.t.Fatalf("writes = %q, want exactly one scale", e.kube.writes)
