456	func (e *upstreamEnv) requirePollIntervals() {
457		e.t.Helper()
458		for i, d := range e.clk.sleeps {
459			if d < minPollInterval || d > maxPollInterval {
460				e.t.Errorf("sleep #%d lasts %v, want between %v and %v", i+1, d, minPollInterval, maxPollInterval)
461			}
462		}
463	}
