465	func (e *upstreamEnv) requireNoSecret(err error) {
466		e.t.Helper()
467		said := e.out.String()
468		if err != nil {
469			said += "\n" + err.Error()
470		}
471		for _, banned := range []string{"password", strings.ToLower(secretMarker), strings.ToLower(fakeSecret)} {
472			if strings.Contains(strings.ToLower(said), banned) {
473				e.t.Errorf("said %q, which contains %q", said, banned)
474			}
475		}
476	}
