731	func TestEnsureUpstreamIgnoresTheClaimOfNexus(t *testing.T) {
732		// The claim of Nexus is Pending and listed first; the upstream's is Bound. The
733		// pod is scheduled and not ready for more than pendingGrace whatever the
734		// interval of the wait (it lies between minPollInterval and maxPollInterval):
735		// enough rounds to last pendingGrace at the shortest interval, and a timeout
736		// that the same rounds cannot reach at the longest one.
737		rounds := int(pendingGrace/minPollInterval) + 2
738		p := upstreamParams()
739		p.Timeout = time.Duration(rounds+1) * maxPollInterval
740		pending := roundOf(1, startingPod()).withNexusClaim("Pending")
741		before := append(repeatRound(pending, rounds), roundOf(1, readyPod()).withNexusClaim("Pending"))
742		e := newUpstreamEnv(t, p, before, nil)
743		if err := e.ensure(context.Background()); err != nil {
744			t.Fatalf("EnsureUpstream: %v (the claim of Nexus is not the upstream's business)", err)
745		}
746		e.requireNoWrite()
747		if len(e.clk.sleeps) != rounds {
748			t.Errorf("slept %d times, want %d: one per round that was not ready", len(e.clk.sleeps), rounds)
749		}
750		if el := e.clk.elapsed(); el < pendingGrace {
751			t.Errorf("waited %v, less than pendingGrace %v: the test would not catch a reader of the wrong claim", el, pendingGrace)
752		}
753	}
