897	// serveComponents lists the components of one repository, a page at a time. The
898	// token is the offset of the next page behind an opaque prefix; the last page
899	// carries "continuationToken": null, as Nexus does.
900	func (f *fakeNexus) serveComponents(w http.ResponseWriter, r *http.Request) {
901		if r.Method != http.MethodGet {
902			f.reply(w, r, http.StatusMethodNotAllowed, nil)
903			return
904		}
905		q := r.URL.Query()
906		repo := q.Get("repository")
907		if repo == "" {
908			f.badRequest(w, r, "the repository parameter is required")
909			return
910		}
911		if !f.repoExists(repo) {
912			f.reply(w, r, http.StatusNotFound, nil)
913			return
914		}
915		offset := 0
916		if token := q.Get("continuationToken"); token != "" {
917			if f.laterPageFails != 0 {
918				f.reply(w, r, f.laterPageFails, map[string]any{"message": "injected fault"})
919				return
920			}
921			n, ok := strings.CutPrefix(token, componentTokenPrefix)
922			if !ok {
923				f.badRequest(w, r, "unknown continuation token")
924				return
925			}
926			digits, _, _ := strings.Cut(n, "/")
927			parsed, err := strconv.Atoi(digits)
928			if err != nil || parsed < 0 {
929				f.badRequest(w, r, "unknown continuation token")
930				return
931			}
932			offset = parsed
933		}
934		all := f.components[repo]
935		end := min(offset+f.componentPage, len(all))
936		offset = min(offset, end)
937		items := make([]any, 0, end-offset)
938		for _, c := range all[offset:end] {
939			items = append(items, c.payload(repo))
940		}
941		var token any // null on the last page
942		if end < len(all) {
943			token = componentTokenPrefix + strconv.Itoa(end) + "/=&?"
944		} else if f.loopTokens[repo] {
945			token = componentTokenPrefix + "0/=&?"
946		}
947		f.reply(w, r, http.StatusOK, map[string]any{"items": items, "continuationToken": token})
948	}
