1314	func (f *fakeNexus) decodeRepo(kind string, body []byte) (map[string]any, string) {
1315		m, ok := decodeObject(body)
1316		if !ok {
1317			return nil, "not a JSON object"
1318		}
1319		need := func(path ...string) bool { return jsonAt(m, path...) != nil }
1320		if !nonEmptyString(m, "name") {
1321			return nil, "name is required"
1322		}
1323		if _, isBool := m["online"].(bool); !isBool {
1324			return nil, "online must be a boolean"
1325		}
1326		blob, _ := jsonAt(m, "storage", "blobStoreName").(string)
1327		if !slices.Contains(f.blobStores, blob) {
1328			return nil, "the blob store " + blob + " does not exist"
1329		}
1330		for _, path := range [][]string{
1331			{"storage", "strictContentTypeValidation"}, {"docker", "v1Enabled"}, {"docker", "forceBasicAuth"},
1332		} {
1333			if !need(path...) {
1334				return nil, strings.Join(path, ".") + " is required"
1335			}
1336		}
1337		switch kind {
1338		case "hosted":
1339			if !need("storage", "writePolicy") {
1340				return nil, "storage.writePolicy is required"
1341			}
1342		case "proxy":
1343			if s, _ := jsonAt(m, "proxy", "remoteUrl").(string); s == "" {
1344				return nil, "proxy.remoteUrl is required"
1345			}
1346			for _, path := range [][]string{{"proxy", "contentMaxAge"}, {"proxy", "metadataMaxAge"}, {"dockerProxy", "indexType"}} {
1347				if !need(path...) {
1348					return nil, strings.Join(path, ".") + " is required"
1349				}
1350			}
1351		case "group":
1352			if !need("docker", "httpPort") {
1353				return nil, "docker.httpPort is required"
1354			}
1355			members, isList := jsonAt(m, "group", "memberNames").([]any)
1356			if !isList {
1357				return nil, "group.memberNames must be an array"
1358			}
1359			for _, member := range members {
1360				name, _ := member.(string)
1361				if _, hosted := f.repos["hosted"][name]; !hosted {
1362					if _, proxy := f.repos["proxy"][name]; !proxy {
1363						return nil, "the group member " + name + " does not exist"
1364					}
1365				}
1366			}
1367		}
1368		return m, ""
1369	}
