1398	// jsonAt follows keys through nested objects; nil when any step is absent.
1399	func jsonAt(m map[string]any, keys ...string) any {
1400		var cur any = m
1401		for _, k := range keys {
1402			obj, ok := cur.(map[string]any)
1403			if !ok {
1404				return nil
1405			}
1406			cur = obj[k]
1407		}
1408		return cur
